from stats import mean_nonempty

def test_mean_empty_none():
    assert mean_nonempty([]) is None

def test_mean_single():
    assert mean_nonempty([5]) == 5.0

def test_mean_float():
    assert abs(mean_nonempty([1.5, 2.5]) - 2.0) < 1e-9


